import React, { useState, useEffect } from 'react';
import api from '../services/api';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  stockQuantity: number;
}

const Shop: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<{ [key: string]: number }>({});

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await api.get('/products');
        setProducts(response.data.products || []);
      } catch (error) {
        console.error('Failed to fetch products', error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  const addToCart = (productId: string) => {
    setCart({
      ...cart,
      [productId]: (cart[productId] || 0) + 1,
    });
  };

  const getTotalPrice = () => {
    return Object.entries(cart).reduce((total, [productId, quantity]) => {
      const product = products.find((p) => p.id === productId);
      return total + (product?.price || 0) * quantity;
    }, 0);
  };

  const handleCheckout = async () => {
    if (Object.keys(cart).length === 0) {
      alert('Cart is empty');
      return;
    }

    try {
      for (const [productId, quantity] of Object.entries(cart)) {
        await api.post('/sales', {
          productId,
          quantity,
          paymentMethod: 'wallet',
        });
      }

      alert('Purchase successful!');
      setCart({});
    } catch (error: any) {
      alert(error.response?.data?.message || 'Purchase failed');
    }
  };

  if (loading) return <div className="text-center py-12">Loading products...</div>;

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold text-gray-800">Shop</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {products.map((product) => (
          <div key={product.id} className="card hover:shadow-lg transition">
            <div className="bg-gray-200 h-40 rounded-lg mb-4 flex items-center justify-center">
              📦
            </div>
            <h3 className="text-lg font-bold text-gray-800">{product.name}</h3>
            <p className="text-gray-600 text-sm">{product.category}</p>
            <p className="text-blue-600 font-bold text-xl mt-2">₹{product.price}</p>
            <p className="text-gray-600 text-sm">Stock: {product.stockQuantity}</p>

            <div className="flex gap-2 mt-4">
              <button
                onClick={() => addToCart(product.id)}
                className="flex-1 btn-primary"
                disabled={product.stockQuantity === 0}
              >
                Add to Cart
              </button>
              {cart[product.id] && (
                <span className="px-3 py-2 bg-blue-100 text-blue-600 rounded-lg font-semibold">
                  {cart[product.id]}
                </span>
              )}
            </div>
          </div>
        ))}
      </div>

      {Object.keys(cart).length > 0 && (
        <div className="card bg-blue-50 sticky bottom-6">
          <div className="flex justify-between items-center">
            <div>
              <p className="text-gray-600">Total Items: {Object.values(cart).reduce((a, b) => a + b, 0)}</p>
              <p className="text-2xl font-bold text-blue-600">Total: ₹{getTotalPrice()}</p>
            </div>
            <button onClick={handleCheckout} className="btn-primary">
              Checkout
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Shop;
